function wzDraft(){const f=document.querySelector('form.ewz');const v=id=>{const el=f&&f.querySelector('#n_'+id);return el?el.value.trim():''};const base=f&&f.dataset.id?S.events.find(e=>e.id===f.dataset.id):null;
  const d=base||wzInv.ev||{id:'__wz',acc:me?me.acc:'',no:'EV'+String((S.events.length||0)+1).padStart(3,'0')};
  if(!base){Object.assign(d,{name:v('name')||'Your function',type:v('type')||'Wedding',date:v('date')||today(),start:(f&&f.querySelector('#n_start')||{}).value||'18:00',end:(f&&f.querySelector('#n_end')||{}).value||'22:00',venue:v('venue')||'Venue',address:v('address'),organizer:v('org')||(me?me.name:''),orgMobile:v('orgm'),logo:imgBuf.logo||'',logoW:imgBuf.logoW||0,logoH:imgBuf.logoH||0});d.invCard=null}
  wzInv.ev=d;return d}
function wzInvHtml(){const ev=wzDraft(),c=ivState(ev);c.kind='invite';ivState(ev);if(wzInv.tpl){c.tplK.invite=wzInv.tpl;ivState(ev)}
  return `<div class="stack c3-wzinv" style="gap:8px"><span class="lbl">Invitation card</span><p class="small muted">Tap a card to see it full screen with your function’s name, date and venue. Swipe to see more, then “Select this invitation”.</p>
  <div class="c3-strip">${IW.map(t=>`<button type="button" class="iv-tile ${c.tplK.invite===t.k?'on':''}" data-act="wzInvOpen" data-k="${t.k}"><span class="iv-mini"><span class="iv-mini-in">${ivcHtml(ev,c,{tpl:t.k,mini:1})}</span></span><b>${esc(t.n)}</b></button>`).join('')}</div></div>`}
function wzInvPaint(){const box=document.getElementById('wzInvBox');if(!box)return;box.innerHTML=wzInvHtml();setTimeout(()=>{ivMini();ivFit(box)},30)}
ACT.wzInvOpen=b=>{const ev=wzDraft(),c=ivState(ev);c.kind='invite';ivState(ev);lbS={ev,k:b.dataset.k,wz:1};let lb=document.getElementById('c3Lb');if(!lb){lb=document.createElement('div');lb.id='c3Lb';lb.className='c3-lb';document.body.appendChild(lb)}lbPaint()};
