{const _es=FORMS.evSave;FORMS.evSave=function(f){const isNew=f&&f.dataset&&!f.dataset.edit&&f.classList&&f.classList.contains('ewz'),before=new Set(S.events.map(e=>e.id)),pick=wzInv.tpl;const r=_es.apply(this,arguments);
  const ne=isNew?S.events.find(e=>!before.has(e.id)):null;if(ne&&pick){const c=ivState(ne);c.tplK.invite=pick;ivState(ne);ne.invPicked=pick;save()}if(ne){wzInv.tpl='';wzInv.ev=null}return r}}
{const _ask=ivAsk;ivAsk=function(eid){const ev=S.events.find(e=>e.id===eid);const pk=ev&&ev.invPicked;_ask(eid);if(!pk)return;const c=ivState(ev);c.tplK.invite=pk;ivState(ev);save();
  const g=document.querySelector('.iv-ask-grid');if(g&&!g.querySelector(`[data-k="${pk}"]`)){g.insertAdjacentHTML('afterbegin',`<button type="button" class="iv-tile on" data-act="ivAskPick" data-k="${pk}"><span class="iv-mini"><span class="iv-mini-in">${ivcHtml(ev,c,{tpl:pk,mini:1,kind:'invite'})}</span></span><b>${esc(DZ(pk).n)}</b></button>`);const last=g.lastElementChild;if(g.children.length>6)last.remove()}
  g&&g.querySelectorAll('.iv-tile').forEach(x=>x.classList.toggle('on',x.dataset.k===pk));setTimeout(()=>{ivMini();ivFit($('#modal'))},60)}}
/* thank-you card attached to Thank you messages uses the thank-you designs */
ivPng=async function(ev,size,kind){const c=ivState(ev),h2c=await ivLoadH2C();const host=document.createElement('div');host.className='iv-export';host.innerHTML=ivcHtml(ev,c,{size,kind});document.body.appendChild(host);
  try{mountQR(host)}catch(_){}try{await document.fonts.ready}catch(_){}await Promise.all([...host.querySelectorAll('img')].map(im=>im.complete?0:new Promise(r=>{im.onload=im.onerror=r})));ivFit(host);await new Promise(r=>setTimeout(r,150));
  const cv=await h2c(host.firstElementChild,{scale:2,backgroundColor:null,useCORS:true,logging:false});host.remove();return cv.toDataURL('image/png')};
