/* ================= V67: only received / verified Moi can be a special guest ================= */
const pinOk=m=>!!m&&(m.status==='received'||m.status==='verified');
{const _p=ACT.moiPin;ACT.moiPin=b=>{const m=S.moi.find(x=>x.id===b.dataset.id);if(!m)return;const ev=S.events.find(e=>e.id===m.event_id);const on=ev&&(ev.pins||[]).includes(m.id);
  if(!on&&!pinOk(m)){const w=m.status==='void'?'This entry is deleted (void).':m.status==='rejected'?'This payment was rejected.':'This payment is still waiting to be verified.';return toast(`${w} Only received or verified Moi can be marked as a special guest.`,'bad')}
  if(on&&!pinOk(m)){ev.pins=(ev.pins||[]).filter(id=>id!==m.id);log(ev.id,'Unpinned',`${m.c.name} · not a confirmed entry`);save();if(b.closest('#modal'))closeModal();render();return}
  _p(b)}}
/* when an entry is voided, rejected or set back to pending, its special-guest mark is removed */
function pinClean(){let ch=0;S.events.forEach(ev=>{if(!ev.pins||!ev.pins.length)return;const keep=ev.pins.filter(id=>{const m=S.moi.find(x=>x.id===id);return m&&m.event_id===ev.id&&pinOk(m)});if(keep.length!==ev.pins.length){ev.pins.filter(id=>!keep.includes(id)).forEach(id=>{const m=S.moi.find(x=>x.id===id);if(m)log(ev.id,'Special guest mark removed',`${m.c.name} · ${(STATUS[m.status]||[m.status])[0]}`)});ev.pins=keep;ch++}});return ch}
{const _r=render;render=function(){try{if(pinClean())save()}catch(e){}return _r.apply(this,arguments)}}
Object.assign(TA,{'Only received or verified Moi can be marked as a special guest.':'பெறப்பட்ட அல்லது சரிபார்க்கப்பட்ட மொய் மட்டுமே சிறப்பு விருந்தினராகக் குறிக்க முடியும்.'});


